def fizzbuzz(n):
    """
    Retourne une liste contenant les nombres de 1 à n,
    en remplaçant les multiples de 3 par 'Fizz',
    les multiples de 5 par 'Buzz' et les multiples de 15 par 'FizzBuzz'.
    """
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(i)
    return result
```

